import {mapped} from './nesting.mjs';
import {catalog} from './drawings/plate-engine.mjs';
const n=v=>Number(v.toFixed(6)).toString();
export function poly(p,layer='CUT'){return ['0','LWPOLYLINE','100','AcDbEntity','8',layer,'100','AcDbPolyline','90',String(p.length),'70','1',...p.flatMap(v=>['10',n(v[0]),'20',n(v[1]),...(v[2]?['42',n(v[2])]:[])])];}
const circle=(p,r)=>['0','CIRCLE','100','AcDbEntity','8','HOLES','100','AcDbCircle','10',n(p[0]),'20',n(p[1]),'30','0','40',n(r)];
// Slots preserve the source drill direction; nesting uses an orientation-preserving rotation.
export function plateEntities(p,map=v=>v){if(!p.plate)throw Error('נדרשת פלטה');if(p.warnings.length)throw Error(p.warnings.join('; '));let a=p.plate,out=poly(a.outline.map(map));for(let [i,h] of a.holes.entries()){if(!h.slot)out.push(...circle(map([h.x,h.y]),h.diameter/2));else {let r=h.diameter/2,e=h.slot/2,drill=p.drills?.[i],axis=drill?.slotAxis,dx=1,dy=0;if(axis){if(!a.frame||drill.id!==h.id)throw Error('ייחוס חריץ אינו תואם למקור');dx=axis.reduce((s,v,j)=>s+v*a.frame.x[j],0);dy=axis.reduce((s,v,j)=>s+v*a.frame.y[j],0);let mag=Math.hypot(dx,dy);if(Math.abs(mag-1)>.001)throw Error('כיוון חריץ אינו תקין');dx/=mag;dy/=mag;}else if(p.drills)throw Error('כיוון חריץ חסר');let pts=[[-e,-r],[e,-r],[e,r],[-e,r]].map(([u,v])=>map([h.x+u*dx-v*dy,h.y+u*dy+v*dx]));pts[1][2]=1;pts[3][2]=1;out.push(...poly(pts,'HOLES'));}}return out;}
// Do not merge geometrically different parts under the same mark in a manufacturing export.
export function plateExportGroups(parts){let c=catalog({parts});if(c.errors.length)throw Error('יצוא פלטות חסום: '+c.errors.map(e=>e.id).join(', '));return c.groups.map((g,i)=>({p:g.p,qty:g.qty,ids:g.ids,mark:g.label,file:'P'+String(i+1).padStart(4,'0')+'.dxf'}));}
export function document(entities){let layers=['CUT','HOLES','MARK'],tokens=['0','SECTION','2','HEADER','9','$ACADVER','1','AC1015','9','$INSUNITS','70','4','9','$MEASUREMENT','70','1','0','ENDSEC','0','SECTION','2','TABLES','0','TABLE','2','LAYER','5','1','330','0','100','AcDbSymbolTable','70','3',...layers.flatMap((name,i)=>['0','LAYER','5',String(i+2),'330','1','100','AcDbSymbolTableRecord','100','AcDbLayerTableRecord','2',name,'70','0','62',String(i+1),'6','CONTINUOUS']),'0','ENDTAB','0','ENDSEC','0','SECTION','2','ENTITIES'];let handle=0x100;for(let i=0;i<entities.length;i+=2){tokens.push(entities[i],entities[i+1]);if(entities[i]==='0'&&['LWPOLYLINE','CIRCLE','TEXT'].includes(entities[i+1]))tokens.push('5',(handle++).toString(16));}return [...tokens,'0','ENDSEC','0','EOF'].join('\r\n');}
export const plateDXF=p=>document(plateEntities(p));
export function sheetDXF(s){return document(s.parts.flatMap(item=>[...plateEntities(item.part,p=>mapped(item,p)),'0','TEXT','100','AcDbEntity','8','MARK','100','AcDbText','10',n(item.x+3),'20',n(item.y+3),'30','0','40','4','1',item.part.mark]));}
